import type { BankStatementImportStatementLine } from '../services/kt/bankStatementImportModels';
import { isBatchHubCandidate, isStatementPaymentRow } from './batchStatementLinkEligibility';

export function isMissingBatchFileNote(note?: string): boolean {
  const s = String(note ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .toLowerCase();
  return s.includes('chua co file') && (s.includes('thanh toan lo') || s.includes('batch'));
}

/** GD hub thiếu file lô — cho nhập bổ sung / ref mẫu / phân bổ. */
export function statementNeedsBatchDetailImport(
  line: Pick<
    BankStatementImportStatementLine,
    | 'expenseNote'
    | 'lineStatus'
    | 'counterpartyName'
    | 'bankAccountCode'
    | 'customerCode'
    | 'debitAmount'
    | 'creditAmount'
    | 'suggestedVoucherType'
  >,
  linkedDetailCount: number,
): boolean {
  if ((line.lineStatus || '').toLowerCase() === 'skipped') return false;
  if (linkedDetailCount > 0) return false;
  if (isMissingBatchFileNote(line.expenseNote)) return true;
  // Đã có ĐT danh mục — tạo CT trực tiếp, không hiện «Nhập lô» thay object.
  if ((line.customerCode || '').trim()) return false;
  return isBatchHubCandidate(line) && isStatementPaymentRow(line);
}

export function amountsMatchVnd(a: number, b: number): boolean {
  return Math.abs(Math.round(a || 0) - Math.round(b || 0)) <= 1;
}
