import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Button,
  Input,
  MoneyInput,
  SearchInput,
  SearchTextInput,
  Slideout,
  Tabs,
  type SearchInputConfig,
} from '@linm-soft-org/linm-web-common-components';
import type {
  AppendBankStatementImportBatchDetailsRequest,
  BankStatementImportBatchLine,
  BankStatementImportBatchTemplate,
  BankStatementImportBatchTemplateCategory,
  BankStatementImportBatchTemplateDetail,
  BankStatementImportRow,
  BankStatementImportStatementLine,
} from '../../../../../services/kt/bankStatementImportModels';
import { bankStatementImportService } from '../../../../../services/kt/bankStatementImportService';
import { parseBatchPaymentFile } from '../../../../../utils/batchPaymentParse';
import { extractBulkRefsFromDescription, normalizeBulkRef } from '../../../../../utils/extractBatchRefs';
import {
  gdMoneyColor,
  isDefaultPickerTxCandidate,
} from '../../../../../utils/batchStatementLinkEligibility';
import { amountsMatchVnd } from '../../../../../utils/missingBatchDetail';
import { formatMoneyVnd } from '../../../../../utils/formatters';
import { getApiErrorMessage } from '../../../../../utils/getApiErrorMessage';
import type { CompanyCodeLookupItem } from './createClassifyLookupConfigs';
import { createCompanyCodeSearchConfig } from './createClassifyLookupConfigs';
import styles from './BatchDetailImportSlideout.module.css';

type SourceTab = 'template' | 'upload' | 'manual';

export type BatchDetailDraftRow = {
  key: string;
  beneficiaryName: string;
  accountNumber: string;
  amount: number;
  status: string;
  description: string;
  companyCode: string;
  postingReasonCode?: string;
  contraAccountCode?: string;
  costCode?: string;
};

type ExistingLot = {
  batchRef: string;
  sheetDate?: string;
  lineCount: number;
  successAmount: number;
  lines: BankStatementImportBatchLine[];
};

type Props = {
  isOpen: boolean;
  importId: string;
  line: BankStatementImportStatementLine | null;
  siblingLines?: BankStatementImportStatementLine[];
  existingBatchLines?: BankStatementImportBatchLine[];
  companyCodeSearchConfig?: SearchInputConfig<CompanyCodeLookupItem>;
  canEdit?: boolean;
  saving?: boolean;
  isDirty?: boolean;
  onClose: () => void;
  onApplyDetails: (dto: AppendBankStatementImportBatchDetailsRequest) => void | Promise<void>;
  onAllocate: (opts?: {
    seed?: BankStatementImportBatchTemplateCategory[];
    extraStatementLineIds?: string[];
    batchRef?: string;
  }) => void;
  testIdPrefix: string;
};

function newKey(): string {
  return `r-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
}

function emptyRow(): BatchDetailDraftRow {
  return {
    key: newKey(),
    beneficiaryName: '',
    accountNumber: '',
    amount: 0,
    status: 'Thành công',
    description: '',
    companyCode: '',
  };
}

function statementAmount(l: BankStatementImportStatementLine): number {
  return l.creditAmount || l.debitAmount || l.amount || 0;
}

function normDateKey(d?: string): string {
  if (!d) return '';
  const s = d.trim();
  const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (iso) return `${iso[3].padStart(2, '0')}/${iso[2].padStart(2, '0')}/${iso[1]}`;
  const m = s.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (!m) return s;
  const yyyy = m[3].length === 2 ? `20${m[3]}` : m[3];
  return `${m[1].padStart(2, '0')}/${m[2].padStart(2, '0')}/${yyyy}`;
}

function toPickerRow(l: BankStatementImportStatementLine): BankStatementImportRow {
  return {
    rowIndex: l.rowIndex,
    transactionDate: l.transactionDate,
    referenceCode: l.referenceCode,
    amount: l.amount,
    debitAmount: l.debitAmount,
    creditAmount: l.creditAmount,
    counterpartyName: l.counterpartyName,
    description: l.description,
    bankAccountCode: l.bankAccountCode,
    partnerBankName: l.partnerBankName,
    importReference: l.importReference,
    detectedBatchRefs: l.detectedBatchRefs,
    suggestedVoucherType: (l.suggestedVoucherType === 'bao_no' || l.suggestedVoucherType === 'bao_co'
      || l.suggestedVoucherType === 'unc' || l.suggestedVoucherType === 'ctnb'
      ? l.suggestedVoucherType
      : undefined),
  };
}

function gdRefLabel(l: BankStatementImportStatementLine): string {
  return l.referenceCode?.trim()
    || extractBulkRefsFromDescription(l.description)[0]
    || `#${l.rowIndex}`;
}

function groupExistingLots(lines: BankStatementImportBatchLine[]): ExistingLot[] {
  const map = new Map<string, ExistingLot>();
  for (const l of lines) {
    const ref = (l.batchRef || '').trim();
    if (!ref) continue;
    const key = normalizeBulkRef(ref) || ref;
    const cur = map.get(key);
    if (!cur) {
      map.set(key, {
        batchRef: ref,
        sheetDate: l.sheetDate,
        lineCount: 1,
        successAmount: l.amount || 0,
        lines: [l],
      });
      continue;
    }
    cur.lineCount += 1;
    cur.successAmount += l.amount || 0;
    cur.lines.push(l);
    if (!cur.sheetDate && l.sheetDate) cur.sheetDate = l.sheetDate;
  }
  return [...map.values()].sort((a, b) =>
    (a.sheetDate ?? '').localeCompare(b.sheetDate ?? '') || a.batchRef.localeCompare(b.batchRef),
  );
}

function guessSearch(line: BankStatementImportStatementLine): string {
  const blob = `${line.description ?? ''} ${line.expenseNote ?? ''} ${line.costCode ?? ''}`;
  const n = blob.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[đĐ]/g, 'd').toLowerCase();
  if (n.includes('thuong') || (line.costCode || '').toUpperCase() === 'THUONG') {
    return 'THUONG';
  }
  if (n.includes('luong') || (line.costCode || '').toUpperCase() === 'LUONG') {
    return 'LUONG';
  }
  return extractBulkRefsFromDescription(line.description)[0] || '';
}

export const BatchDetailImportSlideout: React.FC<Props> = ({
  isOpen,
  importId,
  line,
  siblingLines = [],
  existingBatchLines = [],
  companyCodeSearchConfig,
  canEdit = true,
  saving = false,
  isDirty = false,
  onClose,
  onApplyDetails,
  onAllocate,
  testIdPrefix,
}) => {
  const tid = (s: string) => `${testIdPrefix}-${s}`;
  const fileRef = useRef<HTMLInputElement>(null);
  const [tab, setTab] = useState<SourceTab>('template');
  const [pickerTab, setPickerTab] = useState<'lo' | 'gd'>('lo');
  const [batchRef, setBatchRef] = useState('');
  const [rows, setRows] = useState<BatchDetailDraftRow[]>([emptyRow()]);
  const [fileName, setFileName] = useState('');
  const [parseError, setParseError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [templates, setTemplates] = useState<BankStatementImportBatchTemplate[]>([]);
  const [templatesLoading, setTemplatesLoading] = useState(false);
  const [detail, setDetail] = useState<BankStatementImportBatchTemplateDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [mode, setMode] = useState<'one_to_one' | 'category'>('one_to_one');
  const [linkExistingOnly, setLinkExistingOnly] = useState(false);
  const [selectedExtraIds, setSelectedExtraIds] = useState<string[]>([]);
  const [txSearch, setTxSearch] = useState('');
  const [txDateFilter, setTxDateFilter] = useState('');
  const [showAllGiaoDich, setShowAllGiaoDich] = useState(false);

  const gdAmount = line ? statementAmount(line) : 0;
  const detectedRef = line
    ? (extractBulkRefsFromDescription(line.description)[0] || line.referenceCode || '')
    : '';

  useEffect(() => {
    if (!isOpen || !line) return;
    setTab('template');
    setPickerTab('lo');
    setBatchRef(detectedRef);
    setRows([emptyRow()]);
    setFileName('');
    setParseError(null);
    setDetail(null);
    setSearch(guessSearch(line));
    setMode('one_to_one');
    setLinkExistingOnly(false);
    setSelectedExtraIds([]);
    setTxSearch('');
    setTxDateFilter(normDateKey(line.transactionDate));
    setShowAllGiaoDich(false);
  }, [isOpen, line?.id, detectedRef]);

  useEffect(() => {
    if (!isOpen || !importId) return;
    let cancelled = false;
    setTemplatesLoading(true);
    const t = window.setTimeout(() => {
      void bankStatementImportService.listBatchTemplates(importId, search).then(list => {
        if (!cancelled) setTemplates(list ?? []);
      }).catch(() => {
        if (!cancelled) setTemplates([]);
      }).finally(() => {
        if (!cancelled) setTemplatesLoading(false);
      });
    }, 200);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [isOpen, importId, search]);

  const applyDetailToRows = useCallback((d: BankStatementImportBatchTemplateDetail, nextMode: 'one_to_one' | 'category') => {
    setBatchRef(d.batchRef);
    if (nextMode === 'one_to_one') {
      setRows(d.lines.map(l => ({
        key: newKey(),
        beneficiaryName: l.beneficiaryName || '',
        accountNumber: l.accountNumber || '',
        amount: l.amount || 0,
        status: l.status || 'Thành công',
        description: l.description || '',
        companyCode: l.companyCode || '',
        postingReasonCode: undefined,
        contraAccountCode: undefined,
        costCode: undefined,
      })));
      return;
    }
    const cats = d.categories.length > 0 ? d.categories : [{
      costCode: '',
      companyCode: '',
      lineCount: 0,
      amount: 0,
    }];
    setRows(cats.map(c => ({
      key: newKey(),
      beneficiaryName: c.costCode ? `Hạng mục ${c.costCode}` : 'Hạng mục',
      accountNumber: '',
      amount: 0,
      status: 'Thành công',
      description: c.postingReasonCode || '',
      companyCode: c.companyCode || '',
      postingReasonCode: c.postingReasonCode,
      contraAccountCode: c.contraAccountCode,
      costCode: c.costCode,
    })));
  }, []);

  const pickTemplate = async (tpl: BankStatementImportBatchTemplate) => {
    setDetailLoading(true);
    setParseError(null);
    setLinkExistingOnly(false);
    try {
      const d = await bankStatementImportService.getBatchTemplate(importId, tpl.importVoucherId, tpl.batchRef);
      const nextMode = amountsMatchVnd(d.successAmount, groupAmount) ? 'one_to_one' : 'category';
      setMode(nextMode);
      setDetail(d);
      applyDetailToRows(d, nextMode);
    } catch (err: unknown) {
      setParseError(getApiErrorMessage(err, 'Không tải được lô mẫu'));
    } finally {
      setDetailLoading(false);
    }
  };

  const companyLookup = useMemo(
    () => companyCodeSearchConfig ?? createCompanyCodeSearchConfig(),
    [companyCodeSearchConfig],
  );

  const existingLots = useMemo(() => groupExistingLots(existingBatchLines), [existingBatchLines]);

  const pickExistingLot = (lot: ExistingLot) => {
    setLinkExistingOnly(true);
    setDetail(null);
    setParseError(null);
    setBatchRef(lot.batchRef);
    setRows(lot.lines.map(l => ({
      key: newKey(),
      beneficiaryName: l.beneficiaryName || '',
      accountNumber: l.accountNumber || '',
      amount: l.amount || 0,
      status: l.status || 'Thành công',
      description: l.description || '',
      companyCode: l.companyCode || '',
      postingReasonCode: l.postingReasonCode,
      contraAccountCode: l.contraAccountCode,
      costCode: l.costCode,
    })));
  };

  const extraCandidates = useMemo(() => {
    if (!line) return [];
    return siblingLines.filter(s =>
      s.id !== line.id
      && (s.lineStatus || 'Draft').toLowerCase() !== 'skipped'
      && (s.lineStatus || '').toLowerCase() !== 'confirmed'
      && !s.createdVoucherId);
  }, [line, siblingLines]);

  const selectedExtras = useMemo(
    () => extraCandidates.filter(s => selectedExtraIds.includes(s.id)),
    [extraCandidates, selectedExtraIds],
  );

  const extraAmount = selectedExtras.reduce((s, r) => s + statementAmount(r), 0);
  const groupAmount = gdAmount + extraAmount;

  const pickerTxs = useMemo(() => {
    if (!line) return [];
    const main = toPickerRow(line);
    const sameDateKey = normDateKey(line.transactionDate);
    const selectedRefs = [batchRef, detectedRef].map(normalizeBulkRef).filter(Boolean);
    const q = txSearch.trim().toLowerCase();
    return extraCandidates.filter(s => {
      if (txDateFilter && normDateKey(s.transactionDate) !== txDateFilter) return false;
      if (!showAllGiaoDich) {
        const ok = isDefaultPickerTxCandidate(toPickerRow(s), main, {
          sameDateKey,
          rowDateKey: normDateKey(s.transactionDate),
          selectedBatchRefs: selectedRefs,
        });
        if (!ok) return false;
      }
      if (!q) return true;
      const blob = `${s.referenceCode ?? ''} ${s.description ?? ''} ${s.importReference ?? ''}`.toLowerCase();
      return blob.includes(q);
    });
  }, [line, extraCandidates, txDateFilter, txSearch, showAllGiaoDich, batchRef, detectedRef]);

  const txDateOptions = useMemo(() => {
    const set = new Set<string>();
    for (const s of extraCandidates) {
      const k = normDateKey(s.transactionDate);
      if (k) set.add(k);
    }
    if (txDateFilter) set.add(txDateFilter);
    return [...set].sort();
  }, [extraCandidates, txDateFilter]);

  const toggleExtra = (id: string) => {
    setSelectedExtraIds(prev => (prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]));
  };

  const onPickFile = async (file: File | null) => {
    if (!file) return;
    setParseError(null);
    const parsed = await parseBatchPaymentFile(file);
    if (parsed.length === 0) {
      setParseError('Không đọc được dòng thanh toán lô — kiểm tra mẫu MB/TCB.');
      return;
    }
    setFileName(file.name);
    setLinkExistingOnly(false);
    setBatchRef(parsed[0].batchRef || batchRef || detectedRef);
    setRows(parsed.map(l => ({
      key: newKey(),
      beneficiaryName: l.beneficiaryName || '',
      accountNumber: l.accountNumber || '',
      amount: l.amount || 0,
      status: l.status || 'Thành công',
      description: l.description || '',
      companyCode: l.companyCode || '',
    })));
    setTab('manual');
  };

  const validRows = useMemo(
    () => rows.filter(r => r.beneficiaryName.trim() && r.amount > 0),
    [rows],
  );
  const draftTotal = validRows.reduce((s, r) => s + (r.amount || 0), 0);
  const matched = amountsMatchVnd(draftTotal, groupAmount);
  const canApply = canEdit && (linkExistingOnly
    ? Boolean(batchRef.trim() || detectedRef)
    : validRows.length > 0);

  const handleApply = async () => {
    if (!line || !canApply) return;
    const dto: AppendBankStatementImportBatchDetailsRequest = {
      statementLineId: line.id,
      batchRef: batchRef.trim() || detectedRef || undefined,
      fileName: fileName || undefined,
      extraStatementLineIds: selectedExtraIds,
      batchLines: linkExistingOnly
        ? []
        : validRows.map((r, i) => ({
          lineIndex: i + 1,
          batchRef: batchRef.trim() || undefined,
          beneficiaryName: r.beneficiaryName.trim(),
          accountNumber: r.accountNumber.trim() || undefined,
          amount: r.amount,
          status: r.status || 'Thành công',
          description: r.description.trim() || undefined,
          sheetDate: line.transactionDate,
          companyCode: r.companyCode.trim() || undefined,
          sourcePath: fileName || undefined,
        })),
    };
    await onApplyDetails(dto);
  };

  const footer = (
    <div className={styles.footer}>
      <Button
        variant="secondary"
        onClick={() => onAllocate({
          seed: detail && mode === 'category' ? detail.categories : undefined,
          extraStatementLineIds: selectedExtraIds,
          batchRef: batchRef.trim() || detectedRef || undefined,
        })}
        disabled={!canEdit || saving}
        data-testid={tid('allocate')}
      >
        Không kê chi tiết — phân bổ
      </Button>
      <div className={styles.footerRight}>
        <Button variant="secondary" onClick={onClose} disabled={saving} data-testid={tid('cancel')}>
          Hủy
        </Button>
        <Button
          variant="primary"
          onClick={() => void handleApply()}
          loading={saving}
          disabled={!canApply || saving}
          data-testid={tid('apply')}
        >
          {linkExistingOnly ? 'Gắn lô' : 'Áp dụng lô'}
        </Button>
      </div>
    </div>
  );

  return (
    <Slideout
      isOpen={isOpen}
      onClose={onClose}
      title="Nhập chi tiết lô"
      width="min(980px, 96vw)"
      customFooter={footer}
      data-testid={tid('slideout')}
    >
      {line ? (
        <div className={styles.root}>
          <div className={styles.gdBox} data-testid={tid('gd')}>
            <div><span>Ngày</span><b>{line.transactionDate || '—'}</b></div>
            <div><span>Số tiền GD</span><b>{formatMoneyVnd(gdAmount)}</b></div>
            <div><span>Mã ref</span><b>{detectedRef || '—'}</b></div>
            <p className={styles.gdDesc}>{line.description || '—'}</p>
          </div>
          <div className={styles.sumBar} data-match={draftTotal > 0 || linkExistingOnly ? (matched ? '1' : '0') : ''}>
            <div>
              <span>Sao kê ({1 + selectedExtras.length} GD)</span>
              <b>{formatMoneyVnd(groupAmount)}</b>
            </div>
            <div>
              <span>Tổng lô</span>
              <b>{draftTotal > 0 || linkExistingOnly ? formatMoneyVnd(draftTotal) : '—'}</b>
            </div>
            <div>
              <span>Khớp?</span>
              <b className={matched ? styles.ok : styles.warn}>
                {draftTotal <= 0 && !linkExistingOnly
                  ? '—'
                  : matched
                    ? '✓ Khớp'
                    : `Lệch ${formatMoneyVnd(draftTotal - groupAmount)}`}
              </b>
            </div>
          </div>
          {isDirty ? (
            <p className={styles.warn}>Áp dụng sẽ tải lại chứng từ — phần map chưa lưu sẽ mất.</p>
          ) : null}

          <div className={styles.pickerTabs} data-testid={tid('picker-tabs')}>
            <button
              type="button"
              className={pickerTab === 'lo' ? styles.pickerOn : styles.pickerOff}
              onClick={() => setPickerTab('lo')}
              data-testid={tid('picker-lo')}
            >
              Chọn lô
              <span className={styles.pickerCount}>{existingLots.length + templates.length}</span>
            </button>
            <button
              type="button"
              className={pickerTab === 'gd' ? styles.pickerOn : styles.pickerOff}
              onClick={() => setPickerTab('gd')}
              data-testid={tid('picker-gd')}
            >
              Giao dịch cùng lô
              <span className={styles.pickerCount}>{selectedExtras.length}/{extraCandidates.length}</span>
            </button>
          </div>

          {pickerTab === 'lo' && (
          <>
          <Tabs
            tabs={[
              { id: 'template', label: 'Lô mẫu' },
              { id: 'upload', label: 'Upload file' },
              { id: 'manual', label: 'Nhập tay' },
            ]}
            activeTab={tab}
            onTabChange={id => setTab(id as SourceTab)}
            variant="underline"
            density="compact"
          />

          {tab === 'template' && (
            <div className={styles.section} data-testid={tid('template')}>
              <SearchTextInput
                label="Tìm lô mẫu"
                value={search}
                onChange={setSearch}
                onSearch={() => setSearch(search.trim())}
                placeholder="LUONG, mã lô, số IMP…"
                testId={tid('template-search')}
              />
              {existingLots.length > 0 ? (
                <div className={styles.existBox} data-testid={tid('existing-lots')}>
                  <p className={styles.hint}>Lô trên phiếu này — chọn để gắn, không nhân bản chi tiết</p>
                  {existingLots.map(lot => (
                    <button
                      key={lot.batchRef}
                      type="button"
                      className={`${styles.tplItem} ${linkExistingOnly && batchRef === lot.batchRef ? styles.tplOn : ''}`}
                      onClick={() => pickExistingLot(lot)}
                      data-testid={tid(`exist-${lot.batchRef}`)}
                    >
                      <div className={styles.tplTop}>
                        <b>Lô {lot.batchRef}</b>
                        <span>{formatMoneyVnd(lot.successAmount)}</span>
                      </div>
                      <div className={styles.tplMeta}>
                        {lot.sheetDate || '—'} · {lot.lineCount} dòng
                      </div>
                    </button>
                  ))}
                </div>
              ) : null}
              {templatesLoading ? <p className={styles.hint}>Đang tải lô mẫu…</p> : null}
              <div className={styles.tplList}>
                {templates.map(tpl => (
                  <button
                    key={`${tpl.importVoucherId}-${tpl.batchRef}`}
                    type="button"
                    className={styles.tplItem}
                    onClick={() => void pickTemplate(tpl)}
                    data-testid={tid(`tpl-${tpl.batchRef}`)}
                  >
                    <div className={styles.tplTop}>
                      <b>{tpl.importCode}</b>
                      <span>{formatMoneyVnd(tpl.successAmount)}</span>
                    </div>
                    <div className={styles.tplMeta}>
                      Lô {tpl.batchRef} · {tpl.sheetDate || tpl.monthCode || '—'} · {tpl.lineCount} dòng
                      {tpl.costCodes.length > 0 ? ` · ${tpl.costCodes.join(', ')}` : ''}
                    </div>
                  </button>
                ))}
                {!templatesLoading && templates.length === 0 ? (
                  <p className={styles.hint}>Chưa có lô mẫu — upload file hoặc nhập tay.</p>
                ) : null}
              </div>
              {detailLoading ? <p className={styles.hint}>Đang mở chi tiết lô…</p> : null}
              {detail ? (
                <div className={styles.matchBox} data-testid={tid('match')}>
                  {amountsMatchVnd(detail.successAmount, groupAmount) ? (
                    <p>Khớp tiền {formatMoneyVnd(groupAmount)} — copy 1-1 {detail.lines.length} dòng.</p>
                  ) : (
                    <p>
                      Lệch tiền (mẫu {formatMoneyVnd(detail.successAmount)} ≠ {1 + selectedExtras.length} GD {formatMoneyVnd(groupAmount)})
                      — copy theo hạng mục, reset tiền. Hoặc phân bổ (không bắt đối tượng).
                    </p>
                  )}
                  <div className={styles.modeRow}>
                    <button
                      type="button"
                      className={mode === 'one_to_one' ? styles.modeOn : styles.modeOff}
                      onClick={() => { setMode('one_to_one'); applyDetailToRows(detail, 'one_to_one'); }}
                    >
                      1-1 chi tiết
                    </button>
                    <button
                      type="button"
                      className={mode === 'category' ? styles.modeOn : styles.modeOff}
                      onClick={() => { setMode('category'); applyDetailToRows(detail, 'category'); }}
                    >
                      Hạng mục (reset tiền)
                    </button>
                  </div>
                </div>
              ) : null}
            </div>
          )}

          {tab === 'upload' && (
            <div className={styles.section} data-testid={tid('upload')}>
              <input
                ref={fileRef}
                type="file"
                accept=".xlsx,.xls,.csv"
                hidden
                onChange={e => void onPickFile(e.target.files?.[0] ?? null)}
              />
              <button
                type="button"
                className={styles.drop}
                onClick={() => fileRef.current?.click()}
                data-testid={tid('upload-btn')}
              >
                {fileName || 'Chọn file thanh toán lô (MB / TCB Payroll)'}
              </button>
            </div>
          )}
          </>
          )}

          {pickerTab === 'gd' && (
            <div className={`${styles.section} ${styles.gdPicker}`} data-testid={tid('gd-picker')}>
              <p className={styles.hint}>
                Tick giao dịch cùng lô — mặc định Chi cùng ngày không ĐT hoặc cùng mã ref. Parity bước import.
              </p>
              {selectedExtras.length > 0 ? (
                <div className={styles.selectedList}>
                  {selectedExtras.map(s => (
                    <div key={s.id} className={styles.selectedItem}>
                      <div className={styles.selectedMain}>
                        <span className={styles.kindBadge}>GD</span>
                        <b>{gdRefLabel(s)}</b>
                        <span>{s.transactionDate || '—'}</span>
                        <span style={{ color: gdMoneyColor(toPickerRow(s)) }}>{formatMoneyVnd(statementAmount(s))}</span>
                      </div>
                      <button
                        type="button"
                        className={styles.removeBtn}
                        onClick={() => toggleExtra(s.id)}
                        title="Bỏ chọn GD"
                      >
                        Bỏ
                      </button>
                    </div>
                  ))}
                </div>
              ) : (
                <p className={styles.hint}>Chưa chọn GD phụ — tick ở bảng dưới</p>
              )}
              <div className={styles.txFilter}>
                <label>
                  <span>Ngày</span>
                  <select value={txDateFilter} onChange={e => setTxDateFilter(e.target.value)}>
                    <option value="">Tất cả ngày</option>
                    {txDateOptions.map(d => (
                      <option key={d} value={d}>{d}</option>
                    ))}
                  </select>
                </label>
                <SearchTextInput
                  label="Tìm GD"
                  value={txSearch}
                  onChange={setTxSearch}
                  onSearch={() => setTxSearch(txSearch.trim())}
                  placeholder="Mã FT, nội dung, ref lô…"
                  testId={tid('tx-search')}
                />
                <label className={styles.showAll} title="Hiện mọi GD trên phiếu. Mặc định: Chi cùng ngày không ĐT + cùng mã ref.">
                  <input
                    type="checkbox"
                    checked={showAllGiaoDich}
                    onChange={e => setShowAllGiaoDich(e.target.checked)}
                  />
                  Hiện tất cả giao dịch
                </label>
              </div>
              <div className={`${styles.tableWrap} ${styles.txTableWrap}`}>
                <table className={styles.table}>
                  <thead>
                    <tr>
                      <th style={{ width: 36 }} />
                      <th>Mã GD</th>
                      <th>Ngày</th>
                      <th>Số tiền</th>
                      <th>Nội dung</th>
                    </tr>
                  </thead>
                  <tbody>
                    {pickerTxs.length === 0 ? (
                      <tr>
                        <td colSpan={5} className={styles.hint}>
                          {showAllGiaoDich
                            ? 'Không còn GD (đổi filter Ngày / Nội dung)'
                            : 'Không còn GD phù hợp — mặc định Chi cùng ngày không ĐT · cùng mã ref. Bật «Hiện tất cả» nếu cần.'}
                        </td>
                      </tr>
                    ) : pickerTxs.map(s => {
                      const on = selectedExtraIds.includes(s.id);
                      return (
                        <tr
                          key={s.id}
                          className={on ? styles.rowOn : undefined}
                          onClick={() => toggleExtra(s.id)}
                        >
                          <td>
                            <input
                              type="checkbox"
                              checked={on}
                              onChange={() => toggleExtra(s.id)}
                              onClick={e => e.stopPropagation()}
                            />
                          </td>
                          <td><b>{gdRefLabel(s)}</b></td>
                          <td>{s.transactionDate || '—'}</td>
                          <td style={{ color: gdMoneyColor(toPickerRow(s)), fontWeight: 600 }}>
                            {formatMoneyVnd(statementAmount(s))}
                            {(s.debitAmount ?? 0) > 0 ? ' Chi' : (s.creditAmount ?? 0) > 0 ? ' Thu' : ''}
                          </td>
                          <td title={s.description || undefined}>
                            {(s.description || '—').slice(0, 80)}
                            {(s.description?.length ?? 0) > 80 ? '…' : ''}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          <div className={styles.section}>
            <div className={styles.refRow}>
              <span>Mã lô</span>
              <Input
                value={batchRef}
                onChange={e => setBatchRef(e.target.value)}
                placeholder="Ref lô / INHOUSE"
                data-testid={tid('batch-ref')}
              />
              <Button variant="secondary" onClick={() => setRows(prev => [...prev, emptyRow()])} data-testid={tid('add-row')}>
                Thêm dòng
              </Button>
            </div>
            {parseError ? <p className={styles.err}>{parseError}</p> : null}
            <div className={`${styles.tableWrap} ${styles.draftTableWrap}`}>
              <table className={styles.table}>
                <thead>
                  <tr>
                    <th>Thụ hưởng / hạng mục</th>
                    <th>STK</th>
                    <th>Số tiền</th>
                    <th>Đơn vị</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r, i) => (
                    <tr key={r.key}>
                      <td>
                        <Input
                          value={r.beneficiaryName}
                          onChange={e => setRows(prev => prev.map((x, j) => (j === i ? { ...x, beneficiaryName: e.target.value } : x)))}
                          data-testid={tid(`row-${i}-name`)}
                        />
                      </td>
                      <td>
                        <Input
                          value={r.accountNumber}
                          onChange={e => setRows(prev => prev.map((x, j) => (j === i ? { ...x, accountNumber: e.target.value } : x)))}
                          data-testid={tid(`row-${i}-stk`)}
                        />
                      </td>
                      <td>
                        <MoneyInput
                          value={r.amount}
                          onChange={amount => setRows(prev => prev.map((x, j) => (j === i ? { ...x, amount } : x)))}
                          data-testid={tid(`row-${i}-amt`)}
                        />
                      </td>
                      <td className={styles.companyCell} data-testid={tid(`row-${i}-co`)}>
                        <SearchInput
                          config={companyLookup}
                          value={r.companyCode || ''}
                          primaryDisplay={r.companyCode || ''}
                          onChange={(c: CompanyCodeLookupItem) => setRows(prev => prev.map((x, j) => (j === i ? { ...x, companyCode: c.code } : x)))}
                          onClear={() => setRows(prev => prev.map((x, j) => (j === i ? { ...x, companyCode: '' } : x)))}
                          showLabel={false}
                          showSecondaryInput={false}
                          placeholder="Đơn vị..."
                          className={styles.companyLookup}
                        />
                      </td>
                      <td>
                        <button
                          type="button"
                          className={styles.remove}
                          onClick={() => setRows(prev => (prev.length <= 1 ? [emptyRow()] : prev.filter((_, j) => j !== i)))}
                          aria-label="Xóa dòng"
                        >
                          ×
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <p className={matched ? styles.ok : styles.warn}>
              Tổng dòng {formatMoneyVnd(draftTotal)}
              {matched
                ? ` — khớp ${1 + selectedExtras.length} GD`
                : ` — lệch ${1 + selectedExtras.length} GD ${formatMoneyVnd(groupAmount)}`}
              {linkExistingOnly ? ' · gắn lô có sẵn (không nhân bản)' : ''}
            </p>
          </div>
        </div>
      ) : null}
    </Slideout>
  );
};
