function statementLineAmount(l: BankStatementImportStatementLine): number {
  return l.creditAmount || l.debitAmount || l.amount || 0;
}

function payloadCostCode(line: unknown): string | null {
  if (!line || typeof line !== 'object') return null;
  const v = (line as Record<string, unknown>).costCode;
  return typeof v === 'string' && v.trim() ? v.trim() : null;
}

function payloadRowOrderKey(line: unknown): number {
  if (!line || typeof line !== 'object') return 0;
  const v = (line as Record<string, unknown>).rowOrderKey;
  return typeof v === 'number' ? v : 0;
}

function mapImpAllocToSlideout(a: BankStatementImportAllocation): CashVoucherCompanyAllocationDto {
  return {
    id: a.id,
    targetCompanyCode: a.targetCompanyCode,
    targetCompanyName: a.targetCompanyName,
    amount: a.amount,
    ratio: a.ratio,
    method: a.method,
    sortOrder: a.sortOrder,
    cashVoucherLineId: a.statementLineId || a.batchLineId,
    isRoundingDiff: a.isRoundingDiff,
    costCode: a.costCode,
    rowOrderKey: a.rowOrderKey,
  } as CashVoucherCompanyAllocationDto;
}

