import React, { useMemo } from 'react';
import { Button } from '@linm-soft-org/linm-web-common-components';
import type {
  BankStatementImportAllocation,
  BankStatementImportBatchLine,
  BankStatementImportStatementLine,
} from '../../../../../services/kt/bankStatementImportModels';
import { formatMoneyVnd } from '../../../../../utils/formatters';
import df from '../../../../../styles/documentForm.module.css';
import styles from './StepClassifyImp.module.css';
import { formatImpBatchAllocLabel, formatImpStatementAllocLabel } from './formatImpAllocLineLabel';

const METHOD_LABEL: Record<string, string> = {
  Manual: 'Đích danh',
  Equal: 'Bình quân',
  Ratio: 'Tỷ lệ',
};

export type ClassifyAllocationPanelProps = {
  allocations: BankStatementImportAllocation[];
  scope?: string;
  mismatch?: boolean;
  statementLines: BankStatementImportStatementLine[];
  batchLines: BankStatementImportBatchLine[];
  canEdit?: boolean;
  onAllocateCommon?: () => void;
  onAllocateLine?: (target: {
    statementLineId?: string;
    batchLineId?: string;
    rowOrderKey: number;
    amount: number;
    label: string;
  }) => void;
  testIdPrefix: string;
};

function lineAmount(l: BankStatementImportStatementLine): number {
  return l.creditAmount || l.debitAmount || l.amount || 0;
}

export const ClassifyAllocationPanel: React.FC<ClassifyAllocationPanelProps> = ({
  allocations,
  scope,
  mismatch,
  statementLines,
  batchLines,
  canEdit = false,
  onAllocateCommon,
  onAllocateLine,
  testIdPrefix,
}) => {
  const tid = (s: string) => `${testIdPrefix}-${s}`;
  const scopeLabel = scope === 'ByLine' ? 'theo dòng' : 'full phiếu';
  const method = allocations.find(a => !a.isRoundingDiff)?.method ?? '';
  const methodLabel = METHOD_LABEL[method] ?? method;

  const groups = useMemo(() => {
    const common = allocations.filter(a => (a.sourceKind || 'Common') === 'Common' && !a.statementLineId && !a.batchLineId);
    const byStatement = new Map<string, BankStatementImportAllocation[]>();
    const byBatch = new Map<string, BankStatementImportAllocation[]>();
    for (const a of allocations) {
      if (a.batchLineId) {
        const list = byBatch.get(a.batchLineId) ?? [];
        list.push(a);
        byBatch.set(a.batchLineId, list);
      } else if (a.statementLineId) {
        const list = byStatement.get(a.statementLineId) ?? [];
        list.push(a);
        byStatement.set(a.statementLineId, list);
      }
    }
    return { common, byStatement, byBatch };
  }, [allocations]);

  const renderRows = (rows: BankStatementImportAllocation[], keyPrefix: string) =>
    rows.map((a, idx) => (
      <tr key={a.id || `${keyPrefix}-${idx}`} data-testid={tid(`${keyPrefix}-row-${idx}`)}>
        <td>{a.targetCompanyCode}</td>
        <td>{a.targetCompanyName || '—'}</td>
        <td>{a.costCode || '—'}</td>
        <td>{Number(a.ratio) || 0}</td>
        <td>{formatMoneyVnd(a.amount)}</td>
        <td>{a.isRoundingDiff ? 'Làm tròn' : '—'}</td>
      </tr>
    ));

  if (allocations.length === 0) {
    return (
      <div className={`${df.section} ${styles.postingPanel}`} data-testid={tid('empty')}>
        <p className={styles.hint}>
          Chưa phân bổ. Mặc định <strong>full phiếu</strong> — bấm Phân bổ cạnh Đơn vị trên header
          hoặc trên từng dòng (mode theo dòng).
        </p>
        {canEdit && onAllocateCommon ? (
          <Button variant="secondary" onClick={onAllocateCommon} data-testid={tid('empty-common')}>
            Phân bổ full phiếu
          </Button>
        ) : null}
      </div>
    );
  }

  return (
    <div className={`${df.section} ${styles.postingPanel}`} data-testid={tid('panel')}>
      <div className={styles.allocPanelHead}>
        <h3 className={df.sectionTitle} style={{ margin: 0 }}>
          Phân bổ theo đơn vị / mã chi phí
          <span className={styles.allocScopeHint}>
            {methodLabel ? `${methodLabel} · ` : ''}
            {scopeLabel}
          </span>
        </h3>
        {canEdit && onAllocateCommon ? (
          <Button variant="secondary" onClick={onAllocateCommon} data-testid={tid('edit-common')}>
            Sửa full phiếu
          </Button>
        ) : null}
      </div>
      {mismatch ? (
        <p className={styles.allocMismatch} data-testid={tid('mismatch')}>
          Tổng phân bổ lệch số tiền — nhập lại và xác nhận phân bổ trước khi Confirm.
        </p>
      ) : null}

      {groups.common.length > 0 ? (
        <div className={styles.allocGroup} data-testid={tid('group-common')}>
          <div className={styles.allocGroupTitle}>Chứng từ IMP — full phiếu</div>
          <div className={df.tableWrapper}>
            <table className={df.linesTable}>
              <thead>
                <tr>
                  <th>Mã ĐVCS</th>
                  <th>Tên đơn vị</th>
                  <th>Mã CP</th>
                  <th>Tỷ lệ %</th>
                  <th>Số tiền</th>
                  <th>Ghi chú</th>
                </tr>
              </thead>
              <tbody>{renderRows(groups.common, 'common')}</tbody>
            </table>
          </div>
        </div>
      ) : null}

      {[...groups.byStatement.entries()].map(([lineId, rows]) => {
        const line = statementLines.find(l => l.id === lineId);
        const label = line
          ? formatImpStatementAllocLabel(line)
          : `Dòng ${rows[0]?.rowOrderKey || lineId.slice(0, 8)}`;
        const amt = line ? lineAmount(line) : rows.reduce((s, r) => s + (Number(r.amount) || 0), 0);
        return (
          <div key={lineId} className={styles.allocGroup} data-testid={tid(`group-st-${lineId}`)}>
            <div className={styles.allocGroupTitle}>
              Sao kê {label}
              <span className={styles.allocScopeHint}>{formatMoneyVnd(amt)}</span>
              {canEdit && onAllocateLine && line ? (
                <button
                  type="button"
                  className={styles.allocLinkBtn}
                  onClick={() => onAllocateLine({
                    statementLineId: line.id,
                    rowOrderKey: line.rowIndex,
                    amount: lineAmount(line),
                    label,
                  })}
                  data-testid={tid(`edit-st-${line.rowIndex}`)}
                >
                  Sửa dòng
                </button>
              ) : null}
            </div>
            <div className={df.tableWrapper}>
              <table className={df.linesTable}>
                <thead>
                  <tr>
                    <th>Mã ĐVCS</th>
                    <th>Tên đơn vị</th>
                    <th>Mã CP</th>
                    <th>Tỷ lệ %</th>
                    <th>Số tiền</th>
                    <th>Ghi chú</th>
                  </tr>
                </thead>
                <tbody>{renderRows(rows, `st-${lineId}`)}</tbody>
              </table>
            </div>
          </div>
        );
      })}

      {[...groups.byBatch.entries()].map(([lineId, rows]) => {
        const line = batchLines.find(l => l.id === lineId);
        const label = line
          ? formatImpBatchAllocLabel(line)
          : `Dòng lô ${rows[0]?.rowOrderKey || lineId.slice(0, 8)}`;
        const amt = line?.amount ?? rows.reduce((s, r) => s + (Number(r.amount) || 0), 0);
        return (
          <div key={lineId} className={styles.allocGroup} data-testid={tid(`group-bt-${lineId}`)}>
            <div className={styles.allocGroupTitle}>
              {label}
              <span className={styles.allocScopeHint}>{formatMoneyVnd(amt)}</span>
              {canEdit && onAllocateLine && line ? (
                <button
                  type="button"
                  className={styles.allocLinkBtn}
                  onClick={() => onAllocateLine({
                    batchLineId: line.id,
                    rowOrderKey: line.lineIndex,
                    amount: line.amount ?? 0,
                    label,
                  })}
                  data-testid={tid(`edit-bt-${line.lineIndex}`)}
                >
                  Sửa dòng
                </button>
              ) : null}
            </div>
            <div className={df.tableWrapper}>
              <table className={df.linesTable}>
                <thead>
                  <tr>
                    <th>Mã ĐVCS</th>
                    <th>Tên đơn vị</th>
                    <th>Mã CP</th>
                    <th>Tỷ lệ %</th>
                    <th>Số tiền</th>
                    <th>Ghi chú</th>
                  </tr>
                </thead>
                <tbody>{renderRows(rows, `bt-${lineId}`)}</tbody>
              </table>
            </div>
          </div>
        );
      })}
    </div>
  );
};
