import React from 'react';
import {
  formatSaoKeSourceBankLabel,
  type SaoKeSourceBankHeader,
} from '../../../../constants/bankDepositAccount';
import styles from './SaoKeSourceBankBanner.module.css';

export const SaoKeSourceBankBanner: React.FC<{
  header: SaoKeSourceBankHeader;
  testId?: string;
}> = ({ header, testId = 'kt-import-sao-ke-source-bank' }) => {
  const label = formatSaoKeSourceBankLabel(header);
  if (!label && !header.glAccountCode) return null;

  return (
    <div className={styles.banner} data-testid={testId}>
      <span className={styles.label}>Header sao kê</span>
      <span className={styles.value}>{label || '—'}</span>
      {header.glAccountCode && (
        <span className={styles.gl}>HTTK {header.glAccountCode}</span>
      )}
      {header.earlyTcb && (
        <span className={styles.note}>505566 — cho phép 11217 trước 2026</span>
      )}
    </div>
  );
};
